use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;

fn increment(c: &AtomicUsize) {
    let mut observed = c.load(Ordering::SeqCst);

    loop {
        match c.compare_exchange(
            observed,
            observed + 1,
            Ordering::SeqCst,
            Ordering::SeqCst,
        ) {
            Ok(_) => break,
            Err(actual) => observed = actual,
        }
    }
}

fn w1(c: &AtomicUsize) {
    increment(c);
}

fn w2(c: &AtomicUsize) {
    increment(c);
}

fn main() {
    let c = AtomicUsize::new(0);

    thread::scope(|s| {
        let t1 = s.spawn(|| w1(&c));
        let t2 = s.spawn(|| w2(&c));

        let r1 = t1.join();
        let r2 = t2.join();
        r1.unwrap();
        r2.unwrap();
    });

    assert_eq!(c.load(Ordering::SeqCst), 2);
    println!("DONE done=1");
}
