use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn w1(s: Arc<Semaphore>) {
    let mut work = 0;

    let permit = s.acquire();
    work += 1;
    permit.release();

    let permit = s.acquire();
    work += 1;
    permit.release();

    let _ = work;
}

fn w2(s: Arc<Semaphore>) {
    let mut work = 0;

    let permit = s.acquire();
    work += 1;
    permit.release();

    let permit = s.acquire();
    work += 1;
    permit.release();

    let _ = work;
}

fn main() {
    let s = Semaphore::new(1);

    let worker1 = thread::spawn({
        let s = Arc::clone(&s);
        move || w1(s)
    });
    let worker2 = thread::spawn({
        let s = Arc::clone(&s);
        move || w2(s)
    });

    worker1.join().unwrap();
    worker2.join().unwrap();

    println!("DONE done=1");
}
