    ch1: std::sync::mpsc::SyncSender<u32>,
    ch2: std::sync::mpsc::Receiver<u32>,
    shared: Arc<Mutex<usize>>,
    start: Arc<Barrier>,
) {
    start.wait();

    {
        let mut value = shared.lock().unwrap();
        *value += 1;
    }

    ch1.send(1).unwrap();
    let _reply = ch2.recv().unwrap();

    {
        let mut value = shared.lock().unwrap();
        *value += 1;
    }
}

