use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn main() {
    let s = Semaphore::new(1);
    let s1 = Arc::clone(&s);
    let s2 = Arc::clone(&s);

    let h1 = thread::spawn(move || w1(s1));
    let h2 = thread::spawn(move || w2(s2));

    h1.join().unwrap();
    h2.join().unwrap();

    println!("DONE permits=1");
}

fn w1(s: Arc<Semaphore>) {
    let permit = s.acquire();
    let mut work = 0;
    work = 1;
    permit.release();
}

fn w2(s: Arc<Semaphore>) {
    let permit = s.acquire();
    let mut work = 0;
    work = 1;
    permit.release();
}
```

```rust
use std::sync::mpsc::{sync_channel, Receiver, SyncSender};
use std::sync::{Arc, Mutex};
use std::thread;

fn s(ch1: SyncSender<i32>, ch2: Receiver<i32>, shared_lock: Arc<Mutex<usize>>) {
    {
        let mut value = shared_lock.lock().unwrap();
        *value += 1;
    }

    ch1.send(1).unwrap();
    let _reply = ch2.recv().unwrap();
}

fn r(ch1: Receiver<i32>, ch2: SyncSender<i32>, shared_lock: Arc<Mutex<usize>>) {
    {
        let mut value = shared_lock.lock().unwrap();
        *value += 1;
    }

    let value = ch1.recv().unwrap();
    ch2.send(value).unwrap();
}

fn main() {
    let (ch1_tx, ch1_rx) = sync_channel::<i32>(0);
    let (ch2_tx, ch2_rx) = sync_channel::<i32>(0);
    let shared_lock = Arc::new(Mutex::new(0));

    let sender_lock = Arc::clone(&shared_lock);
    let sender = thread::spawn(move || s(ch1_tx, ch2_rx, sender_lock));

    let receiver_lock = Arc::clone(&shared_lock);
    let receiver = thread::spawn(move || r(ch1_rx, ch2_tx, receiver_lock));

    sender.join().unwrap();
    receiver.join().unwrap();

    println!("DONE done=1");
}
