- notifier: semaphore_acquire {"resource": "main::g12"}; semaphore_acquire {"resource": "main::g12"}; mutex_lock {"resource": "main::m"}; condvar_notify_all {"condvar": "main::cv"}; mutex_unlock {"resource": "main::m"}; semaphore_release {"resource": "main::gN"}; semaphore_release {"resource": "main::gN"}; return {}

