    let s = Arc::new(Semaphore::new(1));

    let first = std::thread::spawn({
        let s = Arc::clone(&s);
        move || w1(s)
    });
    let second = std::thread::spawn({
        let s = Arc::clone(&s);
        move || w2(s)
    });

    first.join().unwrap();
    second.join().unwrap();

    println!("DONE permits=1");
}

